    },
    {
      "card_ids": ["C20"],
      "claim": "Suvorexant, a CNS-active heterocyclic drug, shows 82% oral bioavailability in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Nebivolol, a fluorinated ether-containing drug, has an absolute bioavailability of 96% in extensive metabolizers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Balcinrenone has an absolute bioavailability of 52% in a human mass-balance study, still well above the 20% threshold and supportive of high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved high-transfer experimental analogues show absolute oral bioavailability values from about 50% to near 100%, all well above the 20% threshold, and no retrieved evidence supports low bioavailability. The query is therefore predicted high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule itself.",
    "The retrieved analogues are structurally related but not identical, so subtle query-specific absorption or first-pass metabolism liabilities are not directly tested.",
    "No low-bioavailability analogue was retrieved to calibrate potential negative features."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

